describe('403 Error Handling - Access Denied Page', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display access denied page when API returns 403 error', () => {
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 403,
      body: { error: 'Forbidden', message: 'Access denied' }
    }).as('forbiddenRequest');

    cy.get('[data-testid="load-profile-button"]').click();
    cy.wait('@forbiddenRequest');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="access-denied-title"]').should('contain', 'Access Denied');
    cy.get('[data-testid="access-denied-message"]').should('contain', 'Forbidden');
    cy.get('[data-testid="access-denied-description"]').should('contain', 'You do not have permission to access this resource');
    cy.get('[data-testid="back-to-dashboard-button"]').should('be.visible');
    cy.get('[data-testid="back-to-dashboard-button"]').click();
    cy.url().should('include', '/dashboard');
  });

  it('should handle multiple 403 errors and display error state', () => {
    cy.intercept('GET', '/api/user/settings', {
      statusCode: 403,
      body: { error: 'Forbidden', message: 'Access denied' }
    }).as('settingsForbidden');

    cy.get('[data-testid="load-settings-button"]').click();
    cy.wait('@settingsForbidden');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-code"]').should('contain', '43');
    cy.get('[data-testid="error-message"]').should('contain', 'Forbidden');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();
    cy.intercept('GET', '/api/user/settings', {
      statusCode: 200,
      body: { settings: { theme: 'dark', notifications: true } }
    }).as('settingsSuccess');
    cy.wait('@settingsSuccess');
    cy.get('[data-testid="access-denied-page"]').should('not.exist');
    cy.get('[data-testid="settings-page"]').should('be.visible');
    cy.get('[data-testid="settings-title"]').should('contain', 'Settings');
  });
});
